INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (16997, 'zhTW', '呦。$B$B你是要尋找失蹤的夥伴?', '呦。$B$B你是要尋找失蹤的夥伴?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17004 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17004, 'zhTW', '你們必將為此而遭受懲罰，$r。', NULL, '你竟與這些惡靈同流合污?總有一天，你也會葬身火海!', NULL, '<這隻渾身是傷的巨大黑龍，以充滿惡意的眼神直盯著你，一眨也不眨。>', NULL, '<這隻兇猛的黑龍用力掙扎著束縛牠的鎖鏈，你最好保持距離。>', NULL, '束縛著我的鎖鏈不會永遠存在，$c。祈禱當我展開復仇之時，你不會在附近。', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17051 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17051, 'zhTW', '這個矮人的屍體遍體鱗傷，暮光之錘想必以殺戮他為樂。', '這個矮人死狀十分悽慘，暮光之錘的人必定以凌虐他為樂。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17057 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17057, 'zhTW', '你的死期到了。', '你的死期到了。', '儘管幸災樂禍吧，但你終究會明白我們是對的。', '儘管幸災樂禍吧，但你終究會明白我們是對的。', '我現在雖然遭到束縛，但當我主人的復仇降臨這座城市時，他會將我釋放。', '我現在雖然遭到束縛，但當我主人的復仇降臨這座城市時，他會將我釋放。', '我正走在飛昇之路上，任何自不量力、妄想成為英雄的小角色都休想阻止我。', '我正走在飛昇之路上，任何自不量力、妄想成為英雄的小角色都休想阻止我。', '即將終結的是你的生命;而我的人生才剛要開始。', '即將終結的是你的生命;而我的人生才剛要開始。', '等你察覺真相的時候，一切都為時已晚。', '等你察覺真相的時候，一切都為時已晚。', NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17086 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17086, 'zhTW', '在燃刃氏族落敗之後，我們這些大劍師便立誓要解放自己與同胞們遠離惡魔的控制。$B$B這件事情雖然已經辦到了，但是我個人的榮譽依然存有汙點。$B$B我將為部落而戰，並且將這觀念灌輸給其他的戰士們，直到我在戰場上光榮戰死。這就是我唯一的贖罪之道。$B$B那麼，你準備好接受訓練了嗎?', '在燃刃氏族落敗之後，我們這些大劍師便立誓要解放自己與同胞們遠離惡魔的控制。$B$B這件事情雖然已經辦到了，但是我個人的榮譽依然存有汙點。$B$B我將為部落而戰，並且將這觀念灌輸給其他的戰士們，直到我在戰場上光榮戰死。這就是我唯一的贖罪之道。$B$B那麼，你準備好接受訓練了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17087 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17087, 'zhTW', '看守銀行和部落的財寶遠比躲在鐵籠裡收發錢幣和物品來得有意義多了。$B$B我一點也不想跟那些成天拿筆算錢記帳的哥布林交換工作。', '看守銀行和部落的財寶遠比躲在鐵籠裡收發錢幣和物品來得有意義多了。$B$B我一點也不想跟那些成天拿筆算錢記帳的哥布林交換工作。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17126 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17126, 'zhTW', '採集類技能可助你取得生產類專業技能所需的原料，包括採集藥草，挖取礦物、石頭與珠寶，或者是剝取獸皮。\n\n\n\n你可以利用採集類技能來支援相關的生產類技能，或是直接將原料拿到拍賣場出售。', '採集類技能可助你取得生產類專業技能所需的原料，包括採集藥草，挖取礦物、石頭與珠寶，或者是剝取獸皮。\n\n你可以利用採集類技能來支援相關的生產類技能，或是直接將原料拿到拍賣場出售。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17127 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17127, 'zhTW', '生產類專業技能可讓你將各種原物料製作成物品，供應自己或朋友使用，或是拿到拍賣場出售。\n\n\n\n選擇生產類技能時通常會搭配一個相對應的採集類專業技能，以利自行取得所需的製作原料;不過，若是要單純透過拍賣場來購買原料其實也是可行的。', '生產類專業技能可讓你將各種原物料製作成物品，供應自己或朋友使用，或是拿到拍賣場出售。\n\n選擇生產類技能時通常會搭配一個相對應的採集類專業技能，以利自行取得所需的製作原料;不過，若是要單純透過拍賣場來購買原料其實也是可行的。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17128 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17128, 'zhTW', '草藥學能讓你發現與採集野外的藥草，然後拿到拍賣場出售，或是用來支援鏈金術或銘文學。\n\n\n\n技巧純熟的草藥師亦可發揮他們對於大地的知識來醫療自己。', '草藥學能讓你發現與採集野外的藥草，然後拿到拍賣場出售，或是用來支援鏈金術或銘文學。\n\n技巧純熟的草藥師亦可發揮他們對於大地的知識來醫療自己。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17129 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17129, 'zhTW', '採礦能讓你尋找野外與地底的礦點，並且從中挖掘出礦石與石材。然後你可以將這些東西拿到拍賣場出售，或是用來支援鍛造、工程學，以及珠寶設計等專業技能。\n\n\n\n技巧純熟的礦工也將變得更為強壯，進而提高其耐力。\n\n\n\n你必須先向商人或採礦供應商購得采礦鎬，才能夠挖掘礦點。', '採礦能讓你尋找野外與地底的礦點，並且從中挖掘出礦石與石材。然後你可以將這些東西拿到拍賣場出售，或是用來支援鍛造、工程學，以及珠寶設計等專業技能。\n\n技巧純熟的礦工也將變得更為強壯，進而提高其耐力。\n\n你必須先向商人或採礦供應商購得采礦鎬，才能夠挖掘礦點。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17130 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17130, 'zhTW', '剝皮能讓你從殺死的野獸身上剝取和處理其毛皮，然後你可以將這些東西拿到拍賣場出售，或是用來支援制皮技能。\n\n\n\n技巧純熟的剝皮匠因為對解剖學有深入的瞭解，可提高其對目標造成致命一擊的機會。\n\n\n\n你需要剝皮小刀才能夠剝取野獸身上的皮，你可以從商人或制皮供應商買到這樣物品。', '剝皮能讓你從殺死的野獸身上剝取和處理其毛皮，然後你可以將這些東西拿到拍賣場出售，或是用來支援制皮技能。\n\n技巧純熟的剝皮匠因為對解剖學有深入的瞭解，可提高其對目標造成致命一擊的機會。\n\n你需要剝皮小刀才能夠剝取野獸身上的皮，你可以從商人或制皮供應商買到這樣物品。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17131 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17131, 'zhTW', '鏈金術能讓你使用藥草或其他的原料來製作出各式各樣有用的藥劑、藥水、油膏、精鏈藥劑，以及大鍋。而在使用自制的藥劑與精鏈藥劑時，你也可以獲得更強、更久的效果。\n\n\n\n技巧純熟的鏈金術師尚可轉化元素材料與特定的礦物，以供其他專業技能之用。\n\n\n\n鏈金術很適合搭配草藥學，讓你可以採集自己所需的藥草。', '鏈金術能讓你使用藥草或其他的原料來製作出各式各樣有用的藥劑、藥水、油膏、精鏈藥劑，以及大鍋。而在使用自制的藥劑與精鏈藥劑時，你也可以獲得更強、更久的效果。\n\n技巧純熟的鏈金術師尚可轉化元素材料與特定的礦物，以供其他專業技能之用。\n\n鏈金術很適合搭配草藥學，讓你可以採集自己所需的藥草。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17132 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17132, 'zhTW', '鍛造能讓你使用金屬、礦物與礦石來鑄造物品，包括近戰武器、鎖甲、重灌鎧甲、其他專業技能所需的原料，以及可提升裝備戰力的磨刀石和盾刺等物品。\n\n\n\n技巧純熟的的鍛造師可為他們自己的護腕、手套，自己和其他人的腰帶鑽打寶石插槽，以安裝額外的魔法寶石，更進一步提升裝備的威力。\n\n\n\n鍛造很適合搭配採礦，讓你可以採集自己所需的礦石。', '鍛造能讓你使用金屬、礦物與礦石來鑄造物品，包括近戰武器、鎖甲、重灌鎧甲、其他專業技能所需的原料，以及可提升裝備戰力的磨刀石和盾刺等物品。\n\n技巧純熟的的鍛造師可為他們自己的護腕、手套，自己和其他人的腰帶鑽打寶石插槽，以安裝額外的魔法寶石，更進一步提升裝備的威力。\n\n鍛造很適合搭配採礦，讓你可以採集自己所需的礦石。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17133 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17133, 'zhTW', '附魔能讓你為物品附上多種強化的效果，分解魔法物品，以及製作魔杖與魔油。\n\n\n\n技巧純熟的附魔師甚至可為自己的戒指進行附魔，而這是其他人都辦不到的。\n\n\n\n絕大多數的附魔原料都必須透過分解來取得，而分解的物品則會在此過程中銷燬。附魔很適合搭配裁縫，因為你可以分解自己所製作的魔法物品來取得附魔的原料。\n\n\n\n附魔師亦可將魔法附加在皮紙上進行販售，或是留著供日後使用。皮紙與其他有用的附魔材料可透過附魔供應商購得。', '附魔能讓你為物品附上多種強化的效果，分解魔法物品，以及製作魔杖與魔油。\n\n技巧純熟的附魔師甚至可為自己的戒指進行附魔，而這是其他人都辦不到的。\n\n絕大多數的附魔原料都必須透過分解來取得，而分解的物品則會在此過程中銷燬。附魔很適合搭配裁縫，因為你可以分解自己所製作的魔法物品來取得附魔的原料。\n\n附魔師亦可將魔法附加在皮紙上進行販售，或是留著供日後使用。皮紙與其他有用的附魔材料可透過附魔供應商購得。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17134 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17134, 'zhTW', '工程學能讓你製作出各式各樣好用的、驚人的，甚至詭異的東西，像是槍械與瞄準鏡，摩托車，以及機械松鼠。但是，許多東西都只能供你自己或其他的工程師使用，譬如特殊的護目鏡，裝設在腰帶、靴子、手套，披風上的機械裝置，以及飛行器等等。\n\n\n\n工程學很適合搭配採礦，因為多數的原料都是採礦所取得的金屬。\n\n\n\n許多物品的製造必須用到鐵匠之錘，這件物品以及木柄和助熔劑等其他必須材料，均可向商人或工程學供應商購得。', '工程學能讓你製作出各式各樣好用的、驚人的，甚至詭異的東西，像是槍械與瞄準鏡，摩托車，以及機械松鼠。但是，許多東西都只能供你自己或其他的工程師使用，譬如特殊的護目鏡，裝設在腰帶、靴子、手套，披風上的機械裝置，以及飛行器等等。\n\n工程學很適合搭配採礦，因為多數的原料都是採礦所取得的金屬。\n\n許多物品的製造必須用到鐵匠之錘，這件物品以及木柄和助熔劑等其他必須材料，均可向商人或工程學供應商購得。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17135 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17135, 'zhTW', '銘文學能讓你製作出魔法卷軸、雕紋、副手裝備的典籍、暗月卡片，甚至其他專業技能的配方圖紙。\n\n\n\n銘文學很適合搭配草藥學，因為很多原料都是透過研磨採集而來的藥草所取得的。\n\n\n\n你需要一套行家書寫工具組才能進行銘刻，這件物品以及羊皮紙等其他必須材料，均可向銘文學供應商購得。', '銘文學能讓你製作出魔法卷軸、雕紋、副手裝備的典籍、暗月卡片，甚至其他專業技能的配方圖紙。\n\n銘文學很適合搭配草藥學，因為很多原料都是透過研磨採集而來的藥草所取得的。\n\n你需要一套行家書寫工具組才能進行銘刻，這件物品以及羊皮紙等其他必須材料，均可向銘文學供應商購得。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17136 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17136, 'zhTW', '珠寶設計能讓你製作魔法戒指、護身符、飾品，以及切割各式各樣的寶石。\n\n\n\n你可以直接購買珠寶設計所需的寶石，或是「勘探」採礦所取得的礦石，因此這二種專業技能很適合搭配一起學習。\n\n\n\n多數珠寶設計的成品均需用到珠寶匠的工具箱，更高階的物品還需要動用簡單的磨粉機，這些物品均可向珠寶設計供應商購得。', '珠寶設計能讓你製作魔法戒指、護身符、飾品，以及切割各式各樣的寶石。\n\n你可以直接購買珠寶設計所需的寶石，或是「勘探」採礦所取得的礦石，因此這二種專業技能很適合搭配一起學習。\n\n多數珠寶設計的成品均需用到珠寶匠的工具箱，更高階的物品還需要動用簡單的磨粉機，這些物品均可向珠寶設計供應商購得。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17137 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17137, 'zhTW', '制皮能讓你利用皮革、毛皮，還有鱗片等材料製作出護甲、披風、強化護具的甲片，以及其他相似的物品。制皮所需的其他材料可向商人或制皮供應商購得。\n\n\n\n制皮很適合搭配剝皮，以便取得自己所需的製作原料;而染料與線等其他必要材料，則可向商人或制皮供應商購得。\n\n\n\n技巧純熟的制皮師還能進一步強化他們自己的護腕與腿部的護甲。', '制皮能讓你利用皮革、毛皮，還有鱗片等材料製作出護甲、披風、強化護具的甲片，以及其他相似的物品。制皮所需的其他材料可向商人或制皮供應商購得。\n\n制皮很適合搭配剝皮，以便取得自己所需的製作原料;而染料與線等其他必要材料，則可向商人或制皮供應商購得。\n\n技巧純熟的制皮師還能進一步強化他們自己的護腕與腿部的護甲。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17138 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17138, 'zhTW', '裁縫能讓你利用各種不同的布料來製作出護甲、披風、衣物、包包、法術絲線，以及其他相似的物品。你可以透過直接購買的方式，或是從死亡的人形生物身上收集到所需的布料。而染料與線等額外的必要材料則可向商人或裁縫供應商購得。\n\n\n\n技巧純熟的裁縫師尚可利用魔法刺繡來進一步強化他們的披風。\n\n\n\n附魔很適合搭配裁縫，因為他們可分解自己所製造出來的魔法物品。', '裁縫能讓你利用各種不同的布料來製作出護甲、披風、衣物、包包、法術絲線，以及其他相似的物品。你可以透過直接購買的方式，或是從死亡的人形生物身上收集到所需的布料。而染料與線等額外的必要材料則可向商人或裁縫供應商購得。\n\n技巧純熟的裁縫師尚可利用魔法刺繡來進一步強化他們的披風。\n\n附魔很適合搭配裁縫，因為他們可分解自己所製造出來的魔法物品。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17143 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17143, 'zhTW', '嘿，你好!', '嘿，你好!', '甜心，還有位子容得下我一個嗎?', '甜心，還有位子容得下我一個嗎?', '要往我這個方向走嗎?', '要往我這個方向走嗎?', '可以載小女子一程嗎?', '可以載小女子一程嗎?', '馬帝克，你今天看起來真英俊。', '馬帝克，你今天看起來真英俊。', '喔，馬帝克，我可以搭你的便車嗎?', '喔，馬帝克，我可以搭你的便車嗎?', '馬帝克，你是我所認識最勇敢的獸人。', '馬帝克，你是我所認識最勇敢的獸人。', '救救我，馬帝克!我需要你!', '救救我，馬帝克!我需要你!');
DELETE FROM `npc_text_locale` WHERE `ID` = 17167 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17167, 'zhTW', '說明你的來意，$r。', NULL, '我們正盯著你哦，$r...', NULL, '...alvays vatchink!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17175 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17175, 'zhTW', '我們對秘法的秘密已忽視了太久。$B$B你也是來學習的嗎?', '我們對秘法的秘密已忽視了太久。$B$B你也是來學習的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17181 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17181, 'zhTW', '你也是一位研習秘法的學徒?$B$B如果你想學的話，我可以教你如何開啟傳送門的法術。', '你也是一位研習秘法的學徒?$B$B如果你想學的話，我可以教你如何開啟傳送門的法術。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17187 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17187, 'zhTW', '我恐怕幫不了你，$r，但是我相信凱琳·鋼翼應該可以。', '我恐怕幫不了你，$r，但是我相信凱琳·鋼翼應該可以。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17188 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17188, 'zhTW', '我恐怕幫不了你，$r，但是我相信喬吉亞應該可以。', '我恐怕幫不了你，$r，但是我相信喬吉亞應該可以。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17189 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17189, 'zhTW', '嘿，可不可以幫個忙站過去擋一下陽光?$B$B那樣舒服多了...', NULL, '舒諾茲靠我們發了大財...我們的那份呢?!', NULL, '在這裡工作實在太熱了——尤其是穿著這身制服。', NULL, '他們答應我來這裡可以賺大錢。$B$B真是個笑話!', NULL, '他們把我們當狗一樣使喚，卻什麼好處都沒給我們!', NULL, '舒諾茲靠我們發了大財...我們的那份呢?!', NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17192 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17192, 'zhTW', '你覺得咯咯會對你有什麼看法，如果他還在的話?$B$B嗯?', NULL, '在那場儀式搞砸之後，你欠我一個人情，$r。$B$B而我打算來討回來!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17194 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17194, 'zhTW', '穿過這道傳送門，託巴拉德在等著你。', '穿過這道傳送門，託巴拉德在等著你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17200 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17200, 'zhTW', '陶土議會已在暴風要塞西北方的湖中小島上設定了可通往世界各個不同區域的傳送門。\n\n那兒也有來自巴拉丁鐵衛的代表，可協助傳送至託巴拉德。', '陶土議會已在暴風要塞西北方的湖中小島上設定了可通往世界各個不同區域的傳送門。\n\n那兒也有來自巴拉丁鐵衛的代表，可協助傳送至託巴拉德。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17203 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17203, 'zhTW', '陶土議會已在飛艇塔北方的懸崖設定了可通往世界各個不同區域的傳送門。\n\n\n\n那兒也有來自地獄吼先鋒的代表，可協助傳送至託巴拉德。', '陶土議會已在飛艇塔北方的懸崖設定了可通往世界各個不同區域的傳送門。\n\n那兒也有來自地獄吼先鋒的代表，可協助傳送至託巴拉德。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17204 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17204, 'zhTW', '若是你要找位秘法重鑄師，在法師區外頭的附魔商店裡就有一位精靈貴族法師。', '若是你要找位秘法重鑄師，在法師區外頭的附魔商店裡就有一位精靈貴族法師。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17208 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17208, 'zhTW', '<穆蘭獅鷲騎士佇立不動，目光凝視前方，絲毫不理會你。>', '<穆蘭獅鷲騎士佇立不動，目光凝視前方，絲毫不理會你。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17212 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17212, 'zhTW', '杜格拉斯是派你過來討打的嗎?', '杜格拉斯是派你過來討打的嗎?', '想找架打嗎?', '想找架打嗎?', '你看起來很想跟我單挑...', '你看起來很想跟我單挑...', '想找點苦頭吃嗎?', '想找點苦頭吃嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17216 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17216, 'zhTW', '你想找的人是亞當·霍沙克。他在法師區南側內環的地方有個辦事處。$B$B只要他沒有出去探險，他應該都會待在那裡。', '你想找的人是亞當·霍沙克。他在法師區南側內環的地方有個辦事處。$B$B只要他沒有出去探險，他應該都會待在那裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17226 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17226, 'zhTW', '你要找的屍體就叫迪羅·蟲林。他通常位在本鎮的南邊。', '你要找的屍體就叫迪羅·蟲林。他通常位在本鎮的南邊。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17227 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17227, 'zhTW', '我這兒有點忙，$c。你要做什麼?', NULL, '有什麼需要幫忙的嗎?', NULL, 'Aye.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17228 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17228, 'zhTW', '這個獸人受了重傷。', '這個獸人受了重傷。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17229 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17229, 'zhTW', '抱歉，朋友，但我其實是很忙的。$B$B你看，我得負責紀錄指揮官在這邊找到的所有發現。$B$B肯定會很浩瀚深奧的!', NULL, '除了其他事情之外，我正在為舒諾茲指揮官撰寫傳記。$B$B還請你見諒。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17235 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17235, 'zhTW', '你是誰?', '你是誰?', '趕快離開這裡，免得被那些奴隸販子發現!', '趕快離開這裡，免得被那些奴隸販子發現!', '你...是來救我的嗎?', '你...是來救我的嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17251 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17251, 'zhTW', '這個叫舒諾茲的傢伙已證明了是個明智的投資。$B$B很高興我在一開始就入股了。', NULL, '就像家父常說的:要成為一名成功的投資者，需要精明的頭腦、敏銳的直覺，以及永不動搖的勇氣。$B$B我得承認，我老早就嗅到了這個機會。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17266 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17266, 'zhTW', '你是要來接受訓練的嗎，獵人?', '你是要來接受訓練的嗎，獵人?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17299 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17299, 'zhTW', '好心的鐵褲博士教授就在探險者大廳裡。', '鐵褲教授人應該在探險者大廳裡。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17300 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17300, 'zhTW', '你在吉布的草須魔法用品店裡就能找到一位秘法重鑄師，在大鍛爐的獅鷲獸管理員那邊。$B$B他也是個消失很久的精靈貴族，但是他可以幫你搞定。', '你在吉布的草須魔法用品店裡就能找到一位秘法重鑄師，在大鍛爐的獅鷲獸管理員那邊。$B$B他也是個消失很久的精靈貴族，但是他可以幫你搞定。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17302 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17302, 'zhTW', '在力量谷的中央要塞裡有一位血精靈，他是銀月城派來的，叫做貝洛克。他就是你要找的人。', '在力量谷的中央要塞裡有一位血精靈，他是銀月城派來的，叫做貝洛克。他就是你要找的人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17303 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17303, 'zhTW', '法師們應該是在暗影裂口裡。那邊有兩個入口:一個在力量谷和智慧谷的中間，另一個是在暗巷區。', '法師們應該是在暗影裂口裡。那邊有兩個入口:一個在力量谷和智慧谷的中間，另一個是在暗巷區。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17307 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17307, 'zhTW', '走吧，$r。$B$B你對我一點也不重要。', NULL, '<這位使者未曾看你一眼，只是輕蔑地冷笑。>$B$B忙你自己的事去吧，$r。', NULL, '<這名男子幾乎沒有注意到你的存在。很顯然，他對與你交談毫無興趣。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17308 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17308, 'zhTW', '糟糕透了!$B$B有一道可怕的咆哮聲，好像整個地方都聽得到。$B$B可憐的傢伙...$B$B抱歉我得走了—我想我得去喝一杯。', NULL, '我不太確定自己看到了什麼。$B$B一切都在我意識到發生什麼事之前就結束了。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17318 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17318, 'zhTW', '有一位名叫阿魯內爾的學者可以幫助你。你可以在月神殿找到他，他經常和一位歸來的精靈貴族交談。', '有一位學者叫做『疲倦不堪』的漢孟德可以幫你的忙。你可以在月神殿裡找到他，他經常在那邊和歸來的精靈貴族講話。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17319 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17319, 'zhTW', '我認識你嗎?不認識?歡迎加入暮光之錘。', '我認識你嗎?不認識?歡迎加入暮光之錘。', '末日將至!', '末日將至!', '你的護甲上有些血跡，你還好嗎?', '你的護甲上有些血跡，你還好嗎?', '新來的招募兵?你向指揮官報到了嗎?', '新來的招募兵?你向指揮官報到了嗎?', '嘿，你有沒有看到葛羅姆-葛羅姆?一個獸人，大概這麼高。沒有?$B$B嗯，已經一段時間沒人見過他了，大概是開小差跑了吧。', '嘿，你有沒有看到葛羅姆-葛羅姆?一個獸人，大概這麼高。沒有?$B$B嗯，已經一段時間沒人見過他了，大概是開小差跑了吧。', '東邊的枯萎之地似乎在醞釀著什麼大事。$B$B不管是什麼，我都希望能快點結束，讓我們調去更好一點的地方駐紮。', '東邊的枯萎之地似乎在醞釀著什麼大事。$B$B不管是什麼，我都希望能快點結束，讓我們調去更好一點的地方駐紮。', '保持警惕。聽說之前攻擊民眾的那個怪胎可能還在附近出沒。', '保持警惕。聽說之前攻擊民眾的那個怪胎可能還在附近出沒。', '我們把瑪迦莎·怨懟圖騰囚禁在這裡，是不是很奇怪?幸好她所有的圖騰都被摧毀了。$B$B我甚至聽說她毒死了凱恩·血蹄。真希望她是站在我們這邊。', '我們把瑪迦莎·怨懟圖騰囚禁在這裡，是不是很奇怪?幸好她所有的圖騰都被摧毀了。$B$B我甚至聽說她毒死了凱恩·血蹄。真希望她是站在我們這邊。');
DELETE FROM `npc_text_locale` WHERE `ID` = 17323 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17323, 'zhTW', '歐託·灰皮大多都在長者高地的長者大廳裡。去那邊找他，他會幫你。', '歐託·灰皮大多都在長者高地的長者大廳裡。去那邊找他，他會幫你。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17324 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17324, 'zhTW', '你可以在獵人高地上找到日行者的小屋。', '你可以在獵人高地上找到日行者的小屋。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17327 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17327, 'zhTW', '本城的秘法重鑄師是女巫師費菈，她可以幫得了你。她通常是在陽光庭院裡跟她的學徒希丹娜在討論事情。', '本城的秘法重鑄師是女巫師費菈，她可以幫得了你。她通常是在陽光庭院裡跟她的學徒希丹娜在討論事情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17334 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17334, 'zhTW', '『追尋者』波度羅經常會出現在陰鬱城的商店街。是我的話我就會去那裡找他。', '『追尋者』波度羅經常會出現在陰鬱城的商店街。是我的話我就會去那裡找他。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17336 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17336, 'zhTW', '高等精靈博學者法師達莉諾絲是本城最學識淵博的考古學家...而且也是最善於交際的人。$B$B她通常都待在戲法旅舍，就在市中心的北方，在那邊享受氣氛，還有跟店主和投資人討論她驚奇的冒險故事。', '高等精靈博學者法師達莉諾絲是本城最學識淵博的考古學家...而且也是最善於交際的人。$B$B她通常都待在戲法旅舍，就在市中心的北方，在那邊享受氣氛，還有跟店主和投資人討論她驚奇的冒險故事。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17345 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17345, 'zhTW', '想找訓練嗎?沒門，我不是你要找的人。', '想找訓練嗎?沒門，我不是你要找的人。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17346 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17346, 'zhTW', '大塊頭，在找人訓練嗎?', '大塊頭，在找人訓練嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17360 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17360, 'zhTW', '要是萬一我真的有什麼話要跟你講，你應該快跑。', NULL, '你在這裡愚蠢地徘徊，$r，卻渾然不知周遭潛藏著什麼樣的力量。', NULL, '你心中充滿了恐懼，凡人。$B$B我聞得出來。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17419 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17419, 'zhTW', '現在我們既然佔領了這座可悲的島嶼，我們需要做些工作來整頓一番。你能幫我們嗎，$n?', '現在我們既然佔領了這座可悲的島嶼，我們需要做些工作來整頓一番。你能幫我們嗎，$n?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17420 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17420, 'zhTW', '我並不喜歡那個大家都在談論的D區。但是在我們開始使用它之前，我們的確有些工作得進行。', '我並不喜歡那個大家都在談論的D區。但是在我們開始使用它之前，我們的確有些工作得進行。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17421 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17421, 'zhTW', '我猜你現在已經聽說過那個洞了，$r。如果還沒有，你很快就會聽到一大堆關於它的事情。', '我猜你現在已經聽說過那個洞了，$r。如果還沒有，你很快就會聽到一大堆關於它的事情。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17422 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17422, 'zhTW', '歡迎來到託巴拉德，$c。我們在浪費時間，趕快開始工作吧。', '歡迎來到託巴拉德，$c。我們在浪費時間，趕快開始工作吧。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17433 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17433, 'zhTW', '哈羅!', NULL, 'Wakey wakey!', NULL, '我是一棵樹!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17451 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17451, 'zhTW', '看來教徒們已經注意到德魯伊了!$B$B你可以透過傳送門的漩渦看見野性之心營地!穿過它肯定能把你帶回營地。$B$B等你在這裡的事情辦妥，這會是快速離開的好方法。', '看來教徒們已經注意到德魯伊了!$B$B你可以透過傳送門的漩渦看見野性之心營地!穿過它肯定能把你帶回營地。$B$B等你在這裡的事情辦妥，這會是快速離開的好方法。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17459 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17459, 'zhTW', '你可以在鑄造廠附近的遠行者廣場找到『壁壘』艾爾蘇達和其他戰士訓練師們。', '你可以在鑄造廠附近的遠行者廣場找到『壁壘』艾爾蘇達和其他戰士訓練師們。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17461 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17461, 'zhTW', '這附近還有很多事情得處理，$r。你準備好來幫忙了嗎?', '這附近還有很多事情得處理，$r。你準備好來幫忙了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17462 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17462, 'zhTW', '歡迎來到巴拉丁營地。我知道這裡現在看起來不怎麼樣，但只要稍微努力一番，我們就能把這裡整頓得很像樣。', '歡迎來到巴拉丁營地。我知道這裡現在看起來不怎麼樣，但只要稍微努力一番，我們就能把這裡整頓得很像樣。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17463 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17463, 'zhTW', '看起來這裡有做不完的事。每天凌晨三點都會有新的命令，真的很奇怪。', '看起來這裡有做不完的事。每天凌晨三點都會有新的命令，真的很奇怪。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17464 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17464, 'zhTW', '部落在這裡攻勢從不間斷，感覺就像同時在打兩場戰爭。', '部落在這裡攻勢從不間斷，感覺就像同時在打兩場戰爭。\n\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17469 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17469, 'zhTW', '我們可以一起創造歷史!', NULL, '很快，我們的餘興表演就會成為整個艾澤拉斯談論的焦點!', NULL, '人們將會從四面八方前來，見證我們努力的成果，$n。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17494 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17494, 'zhTW', '我很希望能成交，夥伴，我真的這麼希望。但是你必須得先和汙水企業聯合達到崇拜的聲望才行。', '我很希望能成交，夥伴，我真的這麼希望。但是你必須得先和汙水企業聯合達到崇拜的聲望才行。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17495 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17495, 'zhTW', '嗨!我是考爾·沃瑟頓，汙水機動車。$B$B別客氣，到處看看吧。選出你真正想要的機動車!$B$B一輛騎起來很爽的機動車...一輛危險而在生死邊緣遊轉的機動車...一輛能讓你感到驕傲的機動車!$B$B等你決定了，跟我說一聲，我們可以馬上成交。', '嗨!我是考爾·沃瑟頓，汙水機動車。$B$B別客氣，到處看看吧。選出你真正想要的機動車!$B$B一輛騎起來很爽的機動車...一輛危險而在生死邊緣遊轉的機動車...一輛能讓你感到驕傲的機動車!$B$B等你決定了，跟我說一聲，我們可以馬上成交。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17498 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17498, 'zhTW', '他們在谷的東南邊那棟很高的建築物頂樓。', '他們在谷的東南邊那棟很高的建築物頂樓。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17549 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17549, 'zhTW', NULL, '嗯?你要幹嘛?', NULL, '我才懶得跟$g廢柴:垃圾;講話!', NULL, '親愛的，你還配不上我。', NULL, '我在學校時就沒理過你，現在更不可能理你。', NULL, '你身上這套...「服裝」還真是別具一格呢。', NULL, '好啊，我想再來一杯。去幫我倒一杯，動作快點。', NULL, '親愛的，這是貿易王子的派對，沒有邀請函可進不來!', NULL, '$N，對吧?給你個忠告:別讓貿易王子在這裡看到你。他知道你在覬覦他的位子。$B$B大家都知道。');
DELETE FROM `npc_text_locale` WHERE `ID` = 17550 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17550, 'zhTW', NULL, '什麼蠢蛋?!我不跟野蠻人講話!大膽!', NULL, '現在流行怎麼稱呼你們這種東西?蠻子?地精怪?$B$B我搞不清楚了，滾開。', NULL, '你長得又高又壯，可惜需要洗個澡。去跳進水池裡吧。', NULL, '喔不，你該不會是在跟我說話吧!', NULL, '這附近怎麼有股味道?喔，原來是你身上的。$B$B滾遠一點!', NULL, '你叫什麼名字?$B$B還好你們這些蠻子不會說話，不然我還得跟貿易王子告狀，說你有多煩人。$B$B現在快滾!', NULL, '再敢碰我一下，我保證讓他們把你送去暗礁鎮!', NULL, '噁，你真是噁心!為什麼老是那些醜八怪想來搭訕我?!');
DELETE FROM `npc_text_locale` WHERE `ID` = 17552 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17552, 'zhTW', '<你感到非常驚訝，因為小迅猛龍居然能更和你交流。>$B$B$G爸爸:媽媽;...?', NULL, '<你感到非常驚訝，因為小迅猛龍居然能和你交流。>$B$B我飢餓，故我在。', NULL, '<你感到非常驚訝，因為小迅猛龍居然能和你交流。>$B$B「$c」是什麼意思?你是哥布林的$g族長:女族長;嗎?', NULL, '<你感到非常驚訝，因為小迅猛龍居然能和你交流。>$B$B他們叫你$N。這是你獨有的稱呼，還是一種榮譽頭銜?', NULL, '<你感到非常驚訝，因為小迅猛龍居然能和你交流。>$B$B歡迎您。我最近才剛破殼而出，你呢?', NULL, '<你感到非常驚訝，因為小迅猛龍居然能和你交流。>$B$B你們真的會把肉煮熟嗎?真是奇怪。', NULL, '<你感到非常驚訝，因為小迅猛龍居然能和你交流。>$B$B你沒有戴頭盔，這樣會不會降低你的智力?', NULL, '<你感到非常驚訝，因為小迅猛龍居然能和你交流。>$B$B你的指尖又鈍又圓，這就是你要隨身攜帶其他武器來戰鬥的原因嗎?$B$B真是有趣。', NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17615 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17615, 'zhTW', '歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B瑪法裡恩在照看著我們，所以我們永遠是平衡的守衛者。別忘了這一點。', '歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B瑪法裡恩在照看著我們，所以我們永遠是平衡的守衛者。別忘了這一點。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17616 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17616, 'zhTW', '我們的主人瑪法裡恩從夢境中歸來了，$c。他是替我們指引道路的光明燈塔，而我們必須盡一切所能來維持這盞光明。', '我們的主人瑪法裡恩從夢境中歸來了，$c。他是替我們指引道路的光明燈塔，而我們必須盡一切所能來維持這盞光明。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17659 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17659, 'zhTW', '我無法幫助你，$c。', '我無法幫助你，$c。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17745 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17745, 'zhTW', '我很抱歉，$c，但是精靈貴族們的秘法奧秘對你來說永遠會是個秘密。', '我很抱歉，$c，但是精靈貴族們的秘法奧秘對你來說永遠會是個秘密。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17747 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17747, 'zhTW', '現代的魔法跟千年前根本無法相比。即使如此，我們精靈貴族仍然知道許多秘法的奧妙。你準備好進行學習了嗎?', '現代的魔法跟千年前根本無法相比。即使如此，我們精靈貴族仍然知道許多秘法的奧妙。你準備好進行學習了嗎?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
DELETE FROM `npc_text_locale` WHERE `ID` = 17748 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17748, 'zhTW', '你可以在雷酒釀酒廠找到蠻錘部族的哈爾賓·霜錘。他可以教導你薩滿之道。', '你可以在雷酒釀酒廠找到蠻錘部族的哈爾賓·霜錘。他可以教導你薩滿之道。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
