INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17840, 'zhTW', '這裡歡迎任何人前來對火焰表示敬意，$c。雖然有很多盞火焰已並非原先那些，而是熄滅之後重新點燃的。$B$B在陶土議會，我們只是單純對火焰表示敬意，沒有其他任何輕薄舉動。$B$B在這，我們遵照傳統規定來榮耀火焰。你願意加入我們嗎，$n?', '這裡歡迎任何人前來對火焰表示敬意，$c。雖然有很多盞火焰已並非原先那些，而是熄滅之後重新點燃的。$B$B在陶土議會，我們只是單純對火焰表示敬意，沒有其他任何輕薄舉動。$B$B在這，我們遵照傳統規定來榮耀火焰。你願意加入我們嗎，$n?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
