INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17866, 'zhTW', '我們在託巴拉德島上的巴拉丁堡的弟兄十分繁忙，而且在你需要的時候，他們總是沒空理你。我日以繼夜地守在這裡，就是要幫忙處理他們可能會交付給你的任務。', '我們在託巴拉德島上的巴拉丁堡的弟兄十分繁忙，而且在你需要的時候，他們總是沒空理你。我日以繼夜地守在這裡，就是要幫忙處理他們可能會交付給你的任務。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
