INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (17890, 'zhTW', NULL, '有什麼需要布恩巴幫忙的嗎?', NULL, '布恩巴看著你呢，年輕人。', NULL, '我的靈魂會守護著你，$n。', NULL, '靈魂行者的工作可不輕鬆。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
